-- Validation checks: should return role counts (10/5/5/1), exactly 2 per teacher and parent.
SELECT role, count(*) FROM public.users WHERE email LIKE '%@exellence.com' GROUP BY role ORDER BY role;
SELECT sc.school_name, count(DISTINCT s.student_id) AS students, count(DISTINCT t.teacher_id) AS teachers FROM public.schools sc LEFT JOIN public.students s ON s.school_id=sc.school_id LEFT JOIN public.teachers t ON t.school_id=sc.school_id WHERE sc.director_user_id=(SELECT user_id FROM public.users WHERE email='nadia@exellence.com') GROUP BY sc.school_name;
SELECT tu.email AS teacher, c.class_name, c.grade_level, COUNT(DISTINCT e.student_id) AS assigned_students FROM public.teacher_classes tc JOIN public.teachers t ON t.teacher_id=tc.teacher_id JOIN public.users tu ON tu.user_id=t.user_id JOIN public.classes c ON c.class_id=tc.class_id JOIN public.student_enrollments e ON e.class_id=c.class_id AND e.ended_at IS NULL WHERE tu.email LIKE '%@exellence.com' GROUP BY tu.email,c.class_name,c.grade_level ORDER BY c.class_name;
SELECT pu.email AS parent, COUNT(DISTINCT l.student_id) AS linked_children FROM public.parents p JOIN public.users pu ON pu.user_id=p.user_id JOIN public.guardian_student_links l ON l.parent_id=p.parent_id WHERE pu.email LIKE '%@exellence.com' GROUP BY pu.email ORDER BY pu.email;
SELECT u.email, sv.grade_level, c.class_name FROM public.students s JOIN public.users u ON u.user_id=s.user_id JOIN public.student_survey sv ON sv.student_id=s.student_id JOIN public.student_enrollments e ON e.student_id=s.student_id AND e.ended_at IS NULL JOIN public.classes c ON c.class_id=e.class_id WHERE u.email LIKE '%@exellence.com' ORDER BY sv.grade_level,u.email;
DO $$ DECLARE n integer; BEGIN
 SELECT count(*) INTO n FROM public.users WHERE email LIKE '%@exellence.com' AND role='student'; IF n<>10 THEN RAISE EXCEPTION 'Expected 10 students, got %',n; END IF;
 SELECT count(*) INTO n FROM public.users WHERE email LIKE '%@exellence.com' AND role='teacher'; IF n<>5 THEN RAISE EXCEPTION 'Expected 5 teachers, got %',n; END IF;
 SELECT count(*) INTO n FROM public.users WHERE email LIKE '%@exellence.com' AND role='parent'; IF n<>5 THEN RAISE EXCEPTION 'Expected 5 parents, got %',n; END IF;
 SELECT count(*) INTO n FROM public.users WHERE email LIKE '%@exellence.com' AND role='director'; IF n<>1 THEN RAISE EXCEPTION 'Expected 1 director, got %',n; END IF;
 SELECT count(*) INTO n FROM (SELECT p.parent_id FROM public.parents p JOIN public.users u ON u.user_id=p.user_id JOIN public.guardian_student_links gl ON gl.parent_id=p.parent_id WHERE u.email LIKE '%@exellence.com' GROUP BY p.parent_id HAVING count(DISTINCT gl.student_id)=2) q; IF n<>5 THEN RAISE EXCEPTION 'Expected 5 parents with exactly 2 linked children, got %',n; END IF;
 SELECT count(*) INTO n FROM (SELECT t.teacher_id FROM public.teachers t JOIN public.users u ON u.user_id=t.user_id JOIN public.teacher_classes tc ON tc.teacher_id=t.teacher_id JOIN public.student_enrollments e ON e.class_id=tc.class_id AND e.ended_at IS NULL WHERE u.email LIKE '%@exellence.com' GROUP BY t.teacher_id HAVING count(DISTINCT e.student_id)=2) q; IF n<>5 THEN RAISE EXCEPTION 'Expected 5 teachers assigned exactly 2 students, got %',n; END IF;
 RAISE NOTICE 'Exellence Academy integrity checks passed';
END $$;
